import * as T from './vendor/three.module.js';
import {OrbitControls} from './vendor/OrbitControls.js';
import {CATALOG,BY_ID,V} from './engine.js';
import {openSockets,fitBetween} from './inbetween.js';
import {makeRenderPart} from './render-part.js';
export function inbetweenDialog({model,ids,showDialog,commit}){
 const hosts=ids.map(id=>model.parts.find(p=>p.id===id)).filter(Boolean);
 if(hosts.length!==2||hosts.some(p=>!openSockets(model,p.id).length))throw Error('Select two connectors with open sockets, then choose Fit between.');
 const sockets=hosts.map(p=>openSockets(model,p.id));let result=null,closed=false,frame=0,owned=[];
 showDialog(`<h2>Fit between</h2><div class="between-workspace"><div id="between-preview" aria-label="Fitted rod and two fixed connectors"></div><aside><label>Part <select id="between-type">${CATALOG.filter(d=>d.flexi||['r-green','r-white','r-blue','r-yellow','r-red','r-gray'].includes(d.id)).map(d=>`<option value="${d.id}" ${d.id==='f-green190'?'selected':''}>${d.name} · ${d.length.toFixed(1)} mm</option>`).join('')}</select></label>${sockets.map((list,i)=>`<label>Socket ${i?'B':'A'} <select id="between-${i}">${list.map(p=>`<option value="${p.key}">${Number(p.key.slice(4))+1}</option>`).join('')}</select></label>`).join('')}<label>Bend direction <input id="between-bow" type="range" min="0" max="360" step="15" value="0"></label><output id="between-status" role="status"></output><button id="between-apply" class="button">Connect both ends</button><small>Connectors stay fixed. Uses the selected stock length. Bend limits and clearance are unverified.</small></aside></div>`);
 const dialog=document.querySelector('#dialog'),$=s=>dialog.querySelector(s);dialog.classList.add('between-dialog');
 const scene=new T.Scene();scene.background=new T.Color('#202833');scene.add(new T.HemisphereLight(0xffffff,0x506078,3));const light=new T.DirectionalLight(0xffffff,3);light.position.set(80,200,100);scene.add(light);const root=new T.Group();scene.add(root);const camera=new T.PerspectiveCamera(38,1,.1,10000),renderer=new T.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));$('#between-preview').append(renderer.domElement);const controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=true;
 for(let i=0;i<2;i++){const direction=V(hosts[1-i].pos).sub(V(hosts[i].pos)).normalize();$('#between-'+i).value=[...sockets[i]].sort((a,b)=>V(b.dir).dot(direction)-V(a.dir).dot(direction))[0].key;}
 function clear(){for(const g of owned)g.traverse(o=>{o.geometry?.dispose();o.material?.dispose();});owned=[];root.clear();}
 function draw(fit=false){clear();result=null;let display=hosts;try{result=fitBetween(model,{a:hosts[0].id,ap:$('#between-0').value,b:hosts[1].id,bp:$('#between-1').value,type:$('#between-type').value,bow:Number($('#between-bow').value)});display=[...hosts,result.part];$('#between-status').textContent=`${result.gap.toFixed(1)} mm gap · ${result.length.toFixed(1)} mm stock`; }catch(e){$('#between-status').textContent=e.message;}
 $('#between-apply').disabled=!result;$('#between-bow').disabled=!BY_ID[$('#between-type').value].flexi;
 for(const p of display){const g=makeRenderPart(p.type,p);g.position.fromArray(p.pos);g.quaternion.fromArray(p.quat);root.add(g);if(p.path)owned.push(g);}
 for(let i=0;i<2;i++){const socket=sockets[i].find(s=>s.key===$('#between-'+i).value),dot=new T.Mesh(new T.SphereGeometry(3,12,8),new T.MeshBasicMaterial({color:i?0xff4fea:0x69ffcb,depthTest:false}));dot.position.fromArray(socket.pos);dot.renderOrder=5;root.add(dot);owned.push(dot);}
 if(fit){const box=new T.Box3().setFromObject(root),center=box.getCenter(V()),radius=Math.max(20,box.getBoundingSphere(new T.Sphere()).radius);controls.target.copy(center);camera.position.copy(center).add(V([.4,.5,1]).normalize().multiplyScalar(radius/Math.sin(camera.fov*Math.PI/360)*1.15/Math.min(1,camera.aspect)));controls.update();}}
 for(const input of dialog.querySelectorAll('select,input'))input.oninput=()=>draw();$('#between-apply').onclick=()=>{if(!result)return;commit(result.model);dialog.close();};
 const resize=()=>{const r=$('#between-preview').getBoundingClientRect();renderer.setSize(r.width,r.height);camera.aspect=r.width/r.height;camera.updateProjectionMatrix();},observer=new ResizeObserver(resize);observer.observe($('#between-preview'));function animate(){if(closed)return;controls.update();renderer.render(scene,camera);frame=requestAnimationFrame(animate);}function dispose(){if(closed)return;closed=true;cancelAnimationFrame(frame);observer.disconnect();controls.dispose();clear();renderer.dispose();renderer.forceContextLoss();dialog.classList.remove('between-dialog');dialog.removeEventListener('close',dispose);}dialog.addEventListener('close',dispose);resize();draw(true);animate();return dispose;
}
